We define the \define{Ces\`{a}ro{} average} of a function $f$ over positive integers $n \leqslant x$ as 
\begin{equation}\label{def:cesaro}
    \mathop{\mathbb{E}}_{n \leqslant x} f(n) = \frac{1}{\floor{x}} \sum_{n = 1}^{\floor{x}} f(n).
\end{equation}

\label{def:von-mangoldt}
    The \define{von Mangoldt function} \(\Lambda \colon \mathbb{Z} \to \mathbb{C}\) is given by
    \[
        \Lambda(n) =
        \begin{cases}
            \log(p) &\text{if } n = p^k, \text{ where } p \text{ is prime and } k \geqslant 1 \text{ is an integer}\\
            \hfil 0 &\text{else}
        \end{cases}.
    \]
    We will denote the Fourier transform of the von Mangoldt function restricted to \(\{1, \ldots, N\}\) and viewed as a function on \(\mathbb{Z}/N\mathbb{Z}\) by \(\hat{\Lambda}\).

\label{thm:vdc-estimate}
    Let $q$ be a non-negative integer and $f$ be a function with $q + 2$ continuous derivatives on the interval $I \subseteq [X, 2X]$. Assume that there are constants $B_1, B_2$, and $F$ such that 
    \begin{equation}\label{eqn:derv-bound}
        B_1 F X^{-r} \leqslant \lvert f^{(r)}(x)\rvert \leqslant B_2 F X^{-r}
    \end{equation} 
    for all $1 \leqslant r \leqslant q + 2$. Then there is a constant $B = B(B_1,B_2)$ such that 
    \[
        \biggl\lvert \sum_{n \in I} \mathrm{e}\bigl(f(n) \bigr) \biggr\rvert 
        \leqslant B \biggl(F^\frac{1}{2^{q+2}-2}X^{1-\frac{q+2}{2^{q+2}-2}} + \frac{X}{F} \biggr).
    \]

\begin{equation}\label{eqn:derv-bound}
        B_1 F X^{-r} \leqslant \lvert f^{(r)}(x)\rvert \leqslant B_2 F X^{-r}
    \end{equation}

First, unpacking notation yields
   \begin{equation}\label{eqn:just-by-definition}
       \mathop{\mathbb{E}}_{m \leqslant M} \mathop{\mathbb{E}}_{n \leqslant N} \Lambda(n) \Lambda\bigl(n + \floor{m^c} \bigr)
       = \frac{1}{NM} \sum_{m = 0}^{M - 1} \sum_{n = 0}^{N - 1} \Lambda(n) \Lambda\bigl(n + \floor{m^c} \bigr).
   \end{equation}
       We next apply the Fourier inversion formula (\cref{thm:fourier}) to each of the indicator functions in the above right-hand side. To allow us to do so, we shift the domains of \(\Lambda(n)\) and \(\Lambda\bigl(n + \floor{m^c} \bigr)\) to \(\mathbb{Z}/N\mathbb{Z}\) by taking the arguments modulo \(N\):
   \begin{equation*}
       \eqref{eqn:just-by-definition} = \frac{1}{NM} \sum_{m = 0}^{M - 1} \sum_{n = 0}^{N - 1} \Lambda\bigl(n \text{ (mod } N) \bigr) \Lambda\bigl(n + \floor{m^c} \text{ (mod } N)\bigr) + {\rm O} \biggl(\frac{M^c}{N} \log^2{N} \biggr).
   \end{equation*}
   This transformation introduces an error of \({\rm O} \bigl((M^c/N)\log^2{N} \bigr)\) because the difference between \(\Lambda\bigl(n + \floor{m^c} \bigr)\) and \(\Lambda\bigl(n + \floor{m^c} \text{ (mod } N) \bigr)\) is $\lesssim \log N$, and $\Lambda\bigl(n\text{ (mod } N) \bigr) = \Lambda(n) \lesssim \log N$.
   Now,
   \begin{align*}
       \begin{split}
           \eqref{eqn:just-by-definition} &= \frac{1}{NM} \sum_{m = 0}^{M - 1} \sum_{n = 0}^{N - 1} \Biggl(\frac{1}{N} \sum_{\eta = 0}^{N - 1} \hat{\Lambda}(\eta) \mathrm{e}\biggl(\! -\frac{\eta}{N} n \biggr) \Biggr)\\
           &\hphantom{= \frac{1}{NM} \sum_{m = 0}^{M - 1} \sum_{n = 0}^{N - 1}}\ 
           \cdot \Biggl(\frac{1}{N} \sum_{\xi = 0}^{N - 1} \hat{\Lambda}(\xi) \mathrm{e}\biggl(\! -\frac{\xi}{N} \bigl(n + \floor{m^c} \bigr) \biggr) \Biggr) + {\rm O} \biggl(\frac{M^c}{N}\log^2{N} \biggr)
       \end{split}\\
       \begin{split}
           &= \frac{1}{N^2M} \sum_{m = 0}^{M - 1} \, \sum_{\eta,\, \xi = 0}^{N - 1} \hat{\Lambda}(\xi)\hat{\Lambda}(\eta) \mathrm{e}\biggl(\! -\frac{\xi}{N} \floor{m^c} \!\biggr)\\
           &\hphantom{= \frac{1}{NM} \sum_{m = 0}^{M - 1} \, \sum_{n = 0}^{N - 1}}\ 
           \cdot \Biggl(\frac{1}{N} \sum_{n = 0}^{N - 1} \mathrm{e}\biggl(\! -\frac{\xi + \eta}{N} n \biggr)\Biggr) + {\rm O} \biggl(\frac{M^c}{N}\log^2{N} \biggr).
       \end{split}
   \end{align*}
   Note that \(\sum_{n = 0}^{N - 1} \mathrm{e}\bigl(-n(\xi + \eta)/N \bigr) = 0\) unless \(\eta +\xi = N\). So, all of the cross terms cancel, and we are left with the simpler sum
   \begin{align*}
       \mathop{\mathbb{E}}_{m \leqslant M} \mathop{\mathbb{E}}_{n \leqslant N} \Lambda(n) \Lambda\bigl(n + \floor{m^c} \!\bigr)
       &= \frac{1}{N^2M} \sum_{m = 0}^{M - 1} \sum_{\xi = 0}^{N - 1} \bigl\lvert \hat{\Lambda}(\xi) \bigr\rvert^2 \mathrm{e}\biggl(\! -\frac{\xi}{N} \floor{m^c} \!\biggr) + {\rm O} \biggl(\frac{M^c}{N}\log^2{N} \biggr)\\
       &=\frac{1}{N^2} \sum_{\xi = 0}^{N - 1} \bigl\lvert \hat{\Lambda}(\xi) \bigr\rvert^2 \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi}{N} \floor{m^c} \!\biggr) + {\rm O} \biggl(\frac{1}{\log^{Bc-2}{N}}\biggr),
   \end{align*} where in the first step we used that $\hat{\Lambda}(\xi) = \overline{\hat{\Lambda}(-\xi)}$.

Let $b = 4kA + 2Bc + 4k$, where $k = \ceil*{\bigl((\floor{2c} + 1)(\floor{2c} + 2) + 1 \bigr)/2}$, as in \cref{thm:poulias}. We can write
\begin{equation}\label{eqn:main-sum-decomp}
    \sum_{\xi = 0}^{N - 1} \biggl\lvert \frac{\hat{\Lambda}(\xi)}{N} \biggr\rvert^2 \Biggl(\frac{1}{M} \sum_{m = 1}^M \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\Biggr) 
    = \biggl(\frac{1}{N} \sum_{n = 1}^N \Lambda(n) \biggr)^2 + \Sigma_1 + \Sigma_2,
\end{equation}
where
\begin{align*}
    \Sigma_1 &= \sum_{\xi = 1}^{\frac{N}{\log^b N}} \biggl\lvert \frac{\hat{\Lambda}(\xi)}{N} \biggr\rvert^2 \Biggl(\frac{1}{M} \sum_{m=1}^M \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\Biggr)\\
\intertext{and} 
    \Sigma_2 &= \mkern-10mu \sum_{\xi = \frac{N}{\log^b N}}^{\frac{N}{2}} \!\! \biggl\lvert \frac{\hat{\Lambda}(\xi)}{N} \biggr\rvert^2 \Biggl(\frac{1}{M} \sum_{m=1}^M \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\Biggr).
\end{align*}

 We have
 \begin{equation*}
     \sum_{\xi = 1}^{\frac{N}{\log^b N}} \biggl\lvert \frac{\hat{\Lambda}(\xi)}{N} \biggr\rvert^{2}
     \leqslant \sum_{\xi = 1}^{N} \biggl\lvert \frac{\hat{\Lambda}(\xi)}{N} \biggr\rvert^{2}
     \! = \frac{1}{N}\sum_{\xi = 1}^{N} \bigl(\Lambda(\xi)\bigr)^2,
 \end{equation*}
 where the equality holds by Parseval's identity (\cref{thm:parseval}). Now,
 \begin{equation*}
     \frac{1}{N} \sum_{\xi = 1}^{N} \bigl(\Lambda(\xi)\bigr)^2
     \leqslant \frac{1}{N} \biggl(\sum_{\xi = 1}^{N} \Lambda(\xi) \biggr) \max_{\xi} \Lambda(\xi)
     \leqslant \frac{1}{N} \biggl(\sum_{\xi = 1}^{N} \Lambda(\xi) \biggr) \log N.
 \end{equation*}
By the Prime Number Theorem, $\displaystyle \lim_{N \to \infty} \frac{1}{N} \biggl(\sum_{\xi = 1}^{N} \Lambda(\xi) \biggr) = 1$ and the result follows.

\begin{align*}
        \biggl\lvert \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\biggl(\frac{\xi}{N}n \biggr) \biggr\rvert
        &\leqslant C \biggl(\frac{N}{\sqrt{q}} + N^{\frac{4}{5}} + \sqrt{qN} \biggr) \log^4 N\\
        &\leqslant C \biggl(\frac{N}{\log^{\frac{b}{4}} N} + N^{\frac{4}{5}} + \frac{N}{\log^{\frac{b}{2}} N} \biggr) \log^4 N.\\
    \intertext{Thus, since the above holds for all $\xi \in (\log^b N, N/\log^b N]$,}
        \sup_{\mathclap{\log^b N < \xi \leqslant \frac{N}{\log^b N}}}\; \bigl\lvert \hat{\Lambda}(\xi) \bigr\rvert 
        &\leqslant C \biggl(\frac{N}{\log^{\frac{b}{4}} N} + N^{\frac{4}{5}} +\frac{N}{\log^{\frac{b}{2} - 4} N}\biggr)\\
    \intertext{for all $N \geqslant N_0$. Therefore,}
         \sup_{\mathclap{\log^b N < \xi \leqslant \frac{N}{\log^b N}}}\; \bigl\lvert \hat{\Lambda}(\xi) \bigr\rvert
         &= {\rm O}\biggl(\frac{N}{\log^{\frac{b}{4}} N} \biggr),
    \end{align*}

By the Prime Number Theorem (\cref{thm:prime-number-equiv}), there exist $N_1 \in \mathbb{N},  C, t > 0$ such that 
\begin{equation*}
    \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) - 1 \biggr\rvert 
    \leqslant \frac{C}{e^{t\sqrt{\log N}}} 
\end{equation*}
for all \(N \geqslant N_1\).
Now, since $\displaystyle \lim_{N \to \infty} \frac{N}{\log^{m+b} N} = \infty$, there exists $N_2 \in \mathbb{N}$ so that, for all \(N \geqslant N_2\),
\[
    \frac{N}{\log^{m + b} N} \geqslant N_1.
\]
Further, it can be verified that 
\begin{equation*}
    \lim_{N \to \infty} \frac{2C\log^{m + b} N}{e^{t \sqrt{\log \frac{N}{\log^{m + b} N}}}} = 0,
\end{equation*}
so we can find $N_3 \in \mathbb{N}$ such that, for all \(N \geqslant N_3\),
\begin{equation*}
    \frac{2C\log^{m + b} N}{e^{t \sqrt{\log \frac{N}{\log^{m + b} N}}}}
    \leqslant \frac{1}{\log^m N}.
\end{equation*}

With the above in mind, suppose $N \geqslant \max\{N_2, N_3\}$ and let $k = \floor{\log^m N}$. Accordingly,
\begin{align}
    \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\Bigl(\frac{\xi}{N} n \Bigr) \biggr\rvert
    &\leqslant \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) f_k\Bigl(\frac{\xi}{N} n \Bigr) \biggr\rvert 
    + \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \biggl(\mathrm{e}\Bigl(\frac{\xi}{N} n \Bigr) - f_k\Bigl(\frac{\xi}{N} n \Bigr)\biggr)\biggr\rvert \nonumber\\
    &\leqslant \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) f_k\Bigl(\frac{\xi}{N} n \Bigr) \biggr\rvert + \frac{2\pi}{kN} \sum_{n = 0}^{N - 1} \Lambda(n),\label{eqn:from-N-big}
\end{align}
where $f_k \colon \mathbb{R} \to \mathbb{C}$ is the function satisfying $f_k(x) = \mathrm{e}\bigl(\floor{kx}/k \bigr)$.

\cref{eqn:from-N-big} holds for all $\xi \in [0, N - 1]$. Suppose \(r \in \mathbb{N}\) such that $1 \leqslant r \leqslant \log^b N$. Then,
\begin{equation}\label{eqn:restricting-xi}
    \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) f_k\Bigl(\frac{rn}{N} \Bigr) \biggr\rvert 
    = \biggl\lvert \frac{1}{N} \sum_{\xi = 0}^{rk - 1} \mathrm{e}\biggl(\frac{\xi}{k} \biggr) \; \cdot \;
    \smashoperator{\sum_{\mkern26mu \frac{\xi N}{rk} \leqslant n < \frac{(\xi + 1) N}{rk}}}  \Lambda(n) \biggr\rvert.
\end{equation}
Further, for each $\xi = 0, 1, \ldots, rk - 1$,
\begin{align*}
    \biggl\lvert \frac{1}{N} \; \cdot \; \smashoperator{\sum_{\mkern26mu \frac{\xi N}{rk} \leqslant n < \frac{(\xi + 1)N}{rk}}} \Lambda(n) - \frac{1}{rk} \biggr\rvert
    &= \Biggl\lvert \biggl(\frac{\frac{\xi + 1}{rk}}{\frac{(\xi + 1)N}{rk}} \:\smashoperator{\sum_{\mkern14mu n < \frac{(\xi + 1)N}{{rk}}}} \Lambda(n) - \frac{\xi + 1}{rk} \biggr) 
    - \biggl(\frac{\frac{\xi}{rk}}{\frac{\xi N}{rk}} \:\smashoperator{\sum_{\, n < \frac{\xi N}{rk}}} \Lambda(n) - \frac{\xi}{rk} \biggr)\Biggr\rvert\\
    &\leqslant \frac{\xi + 1}{rk} \Biggl\lvert \frac{1}{\frac{(\xi + 1)N}{rk}} \:\smashoperator{\sum_{\mkern14mu n < \frac{(\xi + 1)N}{{rk}}}} \Lambda(n) - 1 \Biggr\rvert 
    + \frac{\xi}{rk} \Biggl\lvert \frac{1}{\frac{\xi N}{rk}} \:\smashoperator{\sum_{\, n < \frac{\xi N}{rk}}} \Lambda(n) - 1 \Biggr\rvert\\
    &\leqslant \frac{2C}{e^{t\sqrt{\log \frac{\xi N}{rk}}}},
\end{align*}
because if $\xi \geqslant 1$, then
\begin{equation*}
    \frac{\xi N}{rk} \geqslant \frac{N}{\log^{m + b} N}\geqslant N_1.
\end{equation*}

Denote $\displaystyle a(\xi) = \frac{1}{N} \;\cdot\; \smashoperator{\sum_{\mkern26mu \frac{\xi N}{rk} \leqslant n < \frac{(\xi + 1)N}{rk}}} \Lambda(n) - \frac{1}{rk}$. We have
\begin{align}
    \biggl\lvert \frac{1}{N} \sum_{\xi = 0}^{rk - 1} \mathrm{e}\biggl(\frac{\xi}{k} \biggr) 
    \;\cdot\;
    \smashoperator{\sum_{\mkern26mu \frac{\xi N}{rk} \leqslant n < \frac{(\xi + 1)N}{rk}}} \Lambda(n) \biggr\rvert
    &= \Biggl\lvert \sum_{\xi = 0}^{rk - 1} \mathrm{e}\biggl(\frac{\xi}{k} \biggr) \biggl(\frac{1}{rk} + a(\xi) \biggr) \Biggr\rvert \nonumber\\
    &= \Biggl\lvert \sum_{\xi = 0}^{rk - 1} \mathrm{e}\biggl(\frac{\xi}{k} \biggr) a(\xi) \Biggr\rvert \nonumber\\
    &\leqslant \frac{2Crk}{e^{t\sqrt{\log \frac{N}{rk}}}} \nonumber\\ 
    &\leqslant \frac{2C\log^{m + b} N}{e^{t \sqrt{\log \frac{N}{\log^{m + b} N}}}} \nonumber\\
    &\leqslant \frac{1}{\log^m N},\label{eqn:bounding-restricted-xi}
\end{align}
where the final inequality holds because $N \geqslant N_3$.

By \cref{eqn:from-N-big}, \cref{eqn:restricting-xi}, and \cref{eqn:bounding-restricted-xi}, we obtain that, for any $\xi \in [1, \log^b N]$,
\begin{align*}
    \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\biggl(\frac{\xi}{N} n \biggr) \biggr\rvert
    &\leqslant \frac{1}{\log^m N} + \frac{2\pi}{kN} \sum_{n = 0}^{N - 1} \Lambda(n).\\
\intertext{Therefore, for all \(N \geqslant \max\{N_2, N_3\}\),}
    \sup_{1 \leqslant \xi \leqslant \log^b N} \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\biggl(\frac{\xi}{N} n \biggr) \biggr\rvert
    &\leqslant \frac{1}{\log^m N} + \frac{2\pi}{kN} \sum_{n = 0}^{N - 1} \Lambda(n).\\
\intertext{So,}
    \sup_{1\leqslant \xi \leqslant \log^b N} \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\biggl(\frac{\xi}{N} n \biggr) \biggr\rvert 
    &= {\rm O} \biggl(\frac{1}{\log^m N} \biggr),
\end{align*} 
as desired.

\begin{align}
        \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\Bigl(\frac{\xi}{N} n \Bigr) \biggr\rvert
        &\leqslant \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) f_k\Bigl(\frac{\xi}{N} n \Bigr) \biggr\rvert 
        + \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \biggl(\mathrm{e}\Bigl(\frac{\xi}{N} n \Bigr) - f_k\Bigl(\frac{\xi}{N} n \Bigr)\biggr)\biggr\rvert \nonumber\\
        &\leqslant \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) f_k\Bigl(\frac{\xi}{N} n \Bigr) \biggr\rvert + \frac{2\pi}{kN} \sum_{n = 0}^{N - 1} \Lambda(n),\label{eqn:from-N-big}
    \end{align}

\begin{align}
        \biggl\lvert \frac{1}{N} \sum_{\xi = 0}^{rk - 1} \mathrm{e}\biggl(\frac{\xi}{k} \biggr) 
        \;\cdot\;
        \smashoperator{\sum_{\mkern26mu \frac{\xi N}{rk} \leqslant n < \frac{(\xi + 1)N}{rk}}} \Lambda(n) \biggr\rvert
        &= \Biggl\lvert \sum_{\xi = 0}^{rk - 1} \mathrm{e}\biggl(\frac{\xi}{k} \biggr) \biggl(\frac{1}{rk} + a(\xi) \biggr) \Biggr\rvert \nonumber\\
        &= \Biggl\lvert \sum_{\xi = 0}^{rk - 1} \mathrm{e}\biggl(\frac{\xi}{k} \biggr) a(\xi) \Biggr\rvert \nonumber\\
        &\leqslant \frac{2Crk}{e^{t\sqrt{\log \frac{N}{rk}}}} \nonumber\\ 
        &\leqslant \frac{2C\log^{m + b} N}{e^{t \sqrt{\log \frac{N}{\log^{m + b} N}}}} \nonumber\\
        &\leqslant \frac{1}{\log^m N},\label{eqn:bounding-restricted-xi}
    \end{align}

\begin{align*}
        \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\biggl(\frac{\xi}{N} n \biggr) \biggr\rvert
        &\leqslant \frac{1}{\log^m N} + \frac{2\pi}{kN} \sum_{n = 0}^{N - 1} \Lambda(n).\\
    \intertext{Therefore, for all \(N \geqslant \max\{N_2, N_3\}\),}
        \sup_{1 \leqslant \xi \leqslant \log^b N} \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\biggl(\frac{\xi}{N} n \biggr) \biggr\rvert
        &\leqslant \frac{1}{\log^m N} + \frac{2\pi}{kN} \sum_{n = 0}^{N - 1} \Lambda(n).\\
    \intertext{So,}
        \sup_{1\leqslant \xi \leqslant \log^b N} \biggl\lvert \frac{1}{N} \sum_{n = 0}^{N - 1} \Lambda(n) \mathrm{e}\biggl(\frac{\xi}{N} n \biggr) \biggr\rvert 
        &= {\rm O} \biggl(\frac{1}{\log^m N} \biggr),
    \end{align*}

\label{lem:poulias-bound}
    Suppose $b, c \in \mathbb{R}$ and \(k \in \mathbb{N}\), with \(b \geqslant 1\), \(c > 2\), and $2k > (\floor{2c} + 1)(\floor{2c} + 2) + 1$. If $M = \frac{N^{1/c}}{\log^B N}$ for some $B \geqslant 1$, then
    \[
        \sum_{\xi = 1}^{\frac{N}{\log^b N}} \biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\!-\frac{\xi \floor{m^c}}{N}  \biggr) \biggr\rvert^{2k}
        \!\!\! = {\rm O}\bigl(\log^{Bc} N \bigr).
    \]

Suppose $N$ is large (which we will contextualize later). The following holds:
\begin{align*}
    \sum_{\xi = 1}^{\frac{N}{\log^b N}} \biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr) \biggr\rvert^{2k}
    \!\! &\leqslant \sum_{\xi = 1}^{N}\: \biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr) \biggr\rvert^{2k}\\
    &= \sum_{\xi = 0}^{N - 1} \biggl(\mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\biggr)^k \biggl(\overline{\mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)}\biggr)^k\\
    \begin{split}
        &= \sum_{\xi = 0}^{N - 1} \Biggl(\frac{1}{M^k} \;\cdot\; 
        \smashoperator{\sum_{\mkern30mu m_1, \ldots, m_k \leqslant M}}\quad\, \mathrm{e}\biggl(\! -\frac{\xi}{N} \bigl(\floor{m_1^c} + \cdots + \floor{m_k^c} \bigr)\biggr)\Biggr)\\
        &\hphantom{= \sum_{\xi = 0}^{N - 1}}\qquad\: \cdot 
        \Biggl(\frac{1}{M^k} \;\cdot\; \smashoperator{\sum_{\mkern20mu m_{k + 1}, \ldots, m_{2k} \leqslant M}}\quad\;\, \mathrm{e}\biggl(\frac{\xi}{N} \bigl(\floor{m_{k+1}^c} + \cdots + \floor{m_{2k}^c} \bigr)\biggr)\Biggr)
    \end{split}\\
    \begin{split}
        &= \frac{1}{M^{2k}} \! \sum_{\xi = 0}^{N - 1} \mkern-25mu \smashoperator[r]{\sum_{\mkern36mu m_1, \ldots, m_{2k} \leqslant M}}\quad\;\, \mathrm{e}\biggl(\! -\frac{\xi}{N} \bigl(\floor{m_1^c} + \cdots + \floor{m_k^c}\\[-1.2em]
        &\hphantom{= \frac{1}{M^{2k}} \! \sum_{\xi = 0}^{N - 1} \mkern-25mu \smashoperator[r]{\sum_{\mkern36mu m_1, \ldots, m_{2k} \leqslant M}}\quad\;\, \mathrm{e}\biggl(\! -\frac{\xi}{N} \bigl(\floor{m_1^c}}\:
        - \floor{m_{k + 1}^c} - \cdots - \floor{m_{2k}^c} \bigr)\biggr).
    \end{split}
\end{align*}

Note that, for any $R \in \mathbb{Z}$,
\begin{equation*}
  \sum_{\xi = 0}^{N - 1} \mathrm{e}\biggl(\! -\frac{\xi}{N} R \biggr) 
  =\begin{cases}
        N &\text{if } N \mid R\\
        \hfil 0 &\text{if } N \nmid R
    \end{cases}.
\end{equation*}

By hypothesis, we take \(N\) sufficiently large to have
\begin{align*}
    \begin{split}
        \bigl\lvert \floor{m_1^c} + \cdots + \floor{m_k^c} - \floor{m_{k + 1}^c} &- \cdots - \floor{m_{2k}^c} \bigr\rvert\\
        &\leqslant \bigl\lvert \floor{m_1^c} - \floor{m_{k + 1}^c} \bigr\rvert + \cdots + \bigl\lvert \floor{m_k^c} - \floor{m_{2k}^c} \bigr\rvert
    \end{split}\\
    &\leqslant k M^c = \frac{kN}{\log^{Bc} N} < N.
\end{align*}
Therefore,
\begin{equation*}
    \sum_{\xi = 1}^{N} \biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr) \biggr\rvert^{2k} 
    \!\!\! = \frac{N}{M^{2k}} \cdot G(M),
\end{equation*}
where $G(M)$ is the number of solutions to the equation 
\begin{equation}\label{eqn:2k-dim-cube}
    \floor{m_1^c} + \cdots + \floor{m_k^c} - \floor{m_{k + 1}^c} - \cdots - \floor{m_{2k}^c} = 0
\end{equation}
inside the $2k$-dimensional cube $\{1, \ldots , M\}^{2k}$. 

Now, suppose that $(m_1, \ldots, m_{2k})$ satisfies \cref{eqn:2k-dim-cube}. Then,
\begin{align}
    \begin{split}\nonumber
        \bigl\lvert m_1^c + \cdots + m_k^c - m_{k + 1}^c &- \cdots - m_{2k}^c \bigr\rvert\\
        &= \bigl\lvert \{m_1^c\} - \{m_{k + 1}^c\} + \cdots + \{m_k^c\} - \{m_{2k}^c\} \bigr\rvert
    \end{split}\\ 
    &\leqslant \bigl\lvert \{m_1^c\} - \{m_{k + 1}^c\} \bigr\rvert + \cdots + \bigl\lvert \{m_k^c\} - \{m_{2k}^c\} \bigr\rvert < k. \label{eqn:diophantine-inequality}
\end{align}
Thus, $G(M)$ is less than or equal to the number of solutions of the above inequality. By Poulias (\cref{thm:poulias}), this number is 
\[
    2k \Omega M^{2k - c} + {\rm o}(M^{2k - c}) = {\rm O}(M^{2k - c}),
\]
where $\Omega$ is a positive constant. So, $G(M) = {\rm O}(M^{2k - c})$ and 
\begin{equation*}
   \sum_{\xi = 1}^{\frac{N}{\log^b N}} \biggl\lvert \mathop{\mathbb{E}}_{m \leqslant M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr) \biggr\rvert^{2k} \!\!\!
   = {\rm O} \biggl(\frac{N}{M^c} \biggr)
