        &\leqslant \;\,\smashoperator{\sup_{\mkern-10mu \frac{N}{\log^b{N}} \leqslant \xi < \frac{N}{2}}}\;\; U(\xi) \log^{A+1} N + \frac{1}{\log^{A + 1} N}.
    \end{align*}

For each $j \in \mathbb{N}$, let $S_j = [2^{j}, 2^{j + 1}) \cap [1, M]$. Then 
\begin{equation}\label{eqn:dyadic-sum}
    \sum_{m \leqslant M} \mathrm{e}\biggl(\Bigl(\! -\frac{\xi}{N} + k \Bigr) m^c \biggr) 
    = \sum_j \sum_{m \in S_j} \mathrm{e}\biggl(\Bigl(\! -\frac{\xi}{N} + k \Bigr) m^c \biggr).
\end{equation}

For fixed $k$ and $\xi$, the inner sum is amenable to the van der Corput estimate \cref{thm:vdc-estimate}. Choose $X = 2^j$ and $q = \ceil{c - 2}$. Then \cref{eqn:derv-bound} is satisfied with $B_i$ depending only on $c$, and $F = (-\xi/N + k) X^c \approx kX^c$ . For the terms involving $\mathrm{e}(km^c)$ and $\mathrm{e}\bigl((k + \xi/N) m^c\bigr)$, the proof is identical, since $kX^c \approx (k + \xi/N) X^c$.
Since \(X/F \lesssim 1\), we obtain
\begin{equation*}
    \sum_{m \in S_j} \mathrm{e}\biggl(\Bigl(\! -\frac{\xi}{N} + k \Bigr) m^c \biggr)
    \lesssim k^\frac{1}{2^{q + 2} -2 } 2^{j \bigl(1 + \frac{c - q - 2}{2^{q + 2} - 2} \bigr)}.
\end{equation*}

Summing over $j$ up to $\floor*{\log_2 M}$ and noting that $j = 2^{j + 1} \approx M$, the upper limit, we obtain 
\begin{equation*}
    \eqref{eqn:dyadic-sum} \lesssim k^{\frac{1}{2^{q + 2} - 2}} M^{1 + \frac{c - q - 2}{2^{q + 2} - 2}}.
\end{equation*}
Thus,
\begin{align*}
    U(\xi) &\lesssim \frac{1}{K} + M^{\frac{c - q - 2}{2^{q + 2} - 2}} \sum_{k \leqslant K} k^{\frac{1}{2^{q + 2} - 2} - 1}\\
    &\lesssim \frac{1}{K} + M^{\frac{c - q - 2}{2^{q + 2} - 2}}K^{\frac{1}{2^{q + 2} - 2}}.
\end{align*}
Choosing $K$ so that the two summands above are equal, we see that $U(\xi) \lesssim M^\frac{c - q - 2}{2^{q + 2} - 1}$, independent of $\xi$.

\begin{equation}\label{eqn:dyadic-sum}
        \sum_{m \leqslant M} \mathrm{e}\biggl(\Bigl(\! -\frac{\xi}{N} + k \Bigr) m^c \biggr) 
