    &\leqslant \;\,\smashoperator[l]{\sup_{\mkern-11mu \frac{N}{\log^b N} \leqslant \xi \leqslant \frac{N}{2}}} \biggl\lvert \frac{1}{M} \sum_{m = 1}^{M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\biggr\rvert 
    \cdot \sum_{r = 0}^{N - 1}\: \biggl\lvert \frac{\hat{\Lambda}(r)}{N} \biggr\rvert^2\\
    &= \;\,\smashoperator[l]{\sup_{\mkern-11mu \frac{N}{\log^b N} \leqslant \xi \leqslant \frac{N}{2}}} \biggl\lvert \frac{1}{M} \sum_{m = 1}^{M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\biggr\rvert 
    \cdot\frac{1}{N} \sum_{r = 0}^{N - 1} \bigl(\Lambda(r) \bigr)^2,
\end{align*}
where the last equality holds due to Parseval's identity (\cref{thm:parseval}).

Now, since 
\begin{equation*}
    \frac{1}{N} \sum_{\xi = 0}^{N - 1} \bigl(\Lambda(\xi)\bigr)^2 
    \leqslant \frac{1}{N} \sum_{\xi = 0}^{N - 1} \Lambda(\xi) \cdot \log N,
\end{equation*}
we have by the Prime Number Theorem that $\frac{1}{N} \sum_{\xi = 0}^{N - 1} \bigl(\Lambda(\xi) \bigr)^2 = {\rm O}(\log N)$. Therefore,
\begin{align*}
    \sup_{\mkern-10mu \frac{N}{\log^b N} \leqslant \xi \leqslant \frac{N}{2}}
    \biggl\lvert \frac{1}{M} \sum_{m = 1}^{M} \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\biggr\rvert 
    \cdot \frac{1}{N}\sum_{r = 0}^{N - 1} \bigl(\Lambda(r)\bigr)^2 
    &= {\rm O}\biggl(\frac{1}{\log^{A + 1} N} \biggr) {\rm O}(\log N)\\
    &= {\rm O}\biggl(\frac{1}{\log^A N} \biggr),
\end{align*}
as required. Combining the above with \cref{prop:estimate-sigma1}, we have 
\begin{equation*}
    \sum_{\xi = 1}^{\frac{N}{2}} \biggl\lvert \frac{\hat{\Lambda}(\xi)}{N} \biggr\rvert^2 \Biggl(\frac{1}{M} \sum_{m = 1}^M \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\Biggr)
    = {\rm O} \biggl(\frac{1}{\log^A N}\biggr),
\end{equation*}
and thus, by symmetry,
\begin{equation*}
    \sum_{\xi = 1}^{N-1} \biggl\lvert \frac{\hat{\Lambda}(\xi)}{N} \biggr\rvert^2 \Biggl(\frac{1}{M} \sum_{m = 1}^M \mathrm{e}\biggl(\! -\frac{\xi \floor{m^c}}{N} \biggr)\Biggr) 
    = {\rm O}\biggl(\frac{1}{\log^A N}\biggr).
\end{equation*}

